import type { DatabaseSync, StatementSync } from 'node:sqlite';

/** Total processing attempts before a job is failed. */
export const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. */
export const RETRY_DELAY_MS = 500;
/** The worker counts as up if its heartbeat is at most this old. */
export const HEARTBEAT_TTL_MS = 3000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A job in the shape returned by the HTTP API. */
export interface JobRecord {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

const COLUMNS = 'seq, id, status, input, steps, fail_attempts, attempts, progress_completed, result_output, error, idempotency_key, run_after, created_at, updated_at';

function toRecord(r: JobRow): JobRecord {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' && r.result_output !== null ? { output: r.result_output } : null,
    error: r.error,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

const timestamp = (): string => new Date().toISOString();

type Param = string | number | null;

/** All SQL touching jobs. Used by both the server and the worker, each with its own connection. */
export class JobStore {
  private readonly statements = new Map<string, StatementSync>();

  constructor(private readonly db: DatabaseSync) {}

  private stmt(sql: string): StatementSync {
    let s = this.statements.get(sql);
    if (!s) {
      s = this.db.prepare(sql);
      this.statements.set(sql, s);
    }
    return s;
  }

  private one<T>(sql: string, ...params: Param[]): T | undefined {
    return this.stmt(sql).get(...params) as unknown as T | undefined;
  }

  /** Runs `fn` inside a write transaction; the lock is taken up front so no other writer can interleave. */
  transaction<T>(fn: () => T): T {
    this.db.exec('BEGIN IMMEDIATE');
    try {
      const out = fn();
      this.db.exec('COMMIT');
      return out;
    } catch (err) {
      this.db.exec('ROLLBACK');
      throw err;
    }
  }

  insertJob(job: { id: string; input: string; steps: number; failAttempts: number; idempotencyKey: string | null }): JobRecord {
    const now = timestamp();
    this.stmt(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(job.id, job.input, job.steps, job.failAttempts, job.idempotencyKey, now, now);
    return this.getJob(job.id)!;
  }

  getJob(id: string): JobRecord | undefined {
    const row = this.one<JobRow>(`SELECT ${COLUMNS} FROM jobs WHERE id = ?`, id);
    return row && toRecord(row);
  }

  findByIdempotencyKey(key: string): JobRecord | undefined {
    const row = this.one<JobRow>(`SELECT ${COLUMNS} FROM jobs WHERE idempotency_key = ?`, key);
    return row && toRecord(row);
  }

  listJobs(): JobRecord[] {
    return (this.stmt(`SELECT ${COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[]).map(toRecord);
  }

